/**
 * WordPress dependencies
 */
import { createContext, useEffect, useState } from '@wordpress/element';
import type { ReactNode } from '@wordpress/element';
import type { Config, ConfigContextValue } from '../../../types';

export const defaultConfig: Config = {
	title: '',
	symbol: '0',
	effect: 'none',
	layout: 'right',
	expand: '',
	orderby: 'name',
	orderdir: 'ASC',
	showcount: false,
	show_empty: false,
	include_or_exclude: 'include',
	expandCategories: [],
};

const defaultContext: ConfigContextValue = {
	config: defaultConfig,
	setConfig: () => undefined,
};

export const ConfigContext = createContext( defaultContext );

type ConfigProviderProps = {
	attributes: Partial< Config >;
	children: ReactNode;
};

export const ConfigProvider = ( {
	attributes,
	children,
}: ConfigProviderProps ) => {
	const initialConfig: Config = { ...defaultConfig, ...attributes };
	const [ config, updateContextConfig ] = useState( initialConfig );

	const setConfig = ( newConfig: Partial< Config > ) => {
		const parsedConfig: Config = { ...defaultConfig, ...newConfig };

		/* global jclCurrentCat */
		if ( typeof jclCurrentCat !== 'undefined' ) {
			parsedConfig.expandCategories = jclCurrentCat
				.split( ',' )
				.map( Number );
		}

		updateContextConfig( parsedConfig );
	};

	useEffect( () => {
		setConfig( attributes );
	}, [ attributes ] );

	return (
		<ConfigContext.Provider value={ { config, setConfig } }>
			{ children }
		</ConfigContext.Provider>
	);
};
